const fs = require('fs');

let data = '';
try {
  data = fs.readFileSync(0, 'utf8');
} catch (e) {
  data = '';
}

const input = (data.trim().split(/\s+/)[0]) || '';

const order = ['C', 'E', 'U', 'P'];
const counts = {};
const dup = {};
for (const s of order) {
  counts[s] = new Set();
  dup[s] = false;
}

for (let i = 0; i + 2 < input.length; i += 3) {
  const n = input.substring(i, i + 2);
  const s = input[i + 2];
  if (counts[s] === undefined) continue;
  if (counts[s].has(n)) {
    dup[s] = true;
  } else {
    counts[s].add(n);
  }
}

const out = order.map(s => {
  if (dup[s]) return 'erro';
  return String(13 - counts[s].size);
});

console.log(out.join('\n'));
